const esc=s=>String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const members=[{name:'陈明远',role:'受访者',title:'老街记忆 · 访谈记录',topic:'老街生活与沿街商铺的变迁',location:'青石巷社区活动室',paragraphs:['问：您从什么时候开始住在青石巷？对这里最早的印象是什么？','答：我是一九八六年搬过来的。那时候街口还有一家修钟表的小店，早上出门，总能听到隔壁早点铺的声音。大家彼此都认识，谁家有事，招呼一声就有人来帮忙。','问：这些年，您觉得老街最大的变化是什么？','答：变化最大的还是沿街的铺子。以前是大家每天都要去的粮店、裁缝店，现在多了咖啡馆和书店。街道更整洁了，但我还是很怀念以前坐在门口聊天的日子。'],note:'后续补充老街旧照片，核对钟表店开业年份。'},{name:'林晓',role:'受访者',title:'街角书店 · 访谈记录',topic:'独立书店与社区公共生活',location:'青石巷街角书店',paragraphs:['问：为什么选择在老街开一家书店？','答：我希望这里不只是卖书的地方，也能让附近的居民有一个坐下来交流的空间。','问：书店和社区之间有哪些联系？','答：每周六我们都会有读书会，有时也邀请老居民来讲讲这条街的故事。'],note:'下次访谈补充读书会活动资料。'},{name:'周建国',role:'受访者',title:'手艺传承 · 访谈记录',topic:'木作手艺与日常生活',location:'青石巷木作工坊',paragraphs:['问：您学习木作有多少年了？','答：从十七岁跟着父亲学起，到现在已经四十多年了。','问：最希望年轻人记住什么？','答：先把一件小东西做好。木头有自己的纹理，顺着它来，东西才结实。'],note:'记录工坊工具名称，补拍制作过程。'}];
let current=0, target='interview', focusRegion='interview', tab='transcript', selected=-1, playPos=204, playing=false, rate=1, recordState='idle', recordSeconds=0, recordingNo=1, pending=true, snapshots=[], dirtyTimer, toastTimer, lastFocus;
const docs=members.map(m=>({paragraphs:[...m.paragraphs],note:m.note}));
const entries=()=>docs[current].paragraphs.map((text,i)=>({text,time:[0,58,204,265][i]??300,speaker:i%2?'陈明远':'访谈人',letter:i%2?'B':'A'}));
const fmt=n=>`${Math.floor(n/60).toString().padStart(2,'0')}:${Math.floor(n%60).toString().padStart(2,'0')}`;
function toast(t){$('#toast').textContent=t;$('#toast').hidden=false;clearTimeout(toastTimer);toastTimer=setTimeout(()=>$('#toast').hidden=true,3500)}
function renderMembers(){ $('#members').innerHTML=members.map((m,i)=>`<button class="nav-row member-button ${i===current?'selected':''}" data-member="${i}"><span class="initial">${esc(m.name[0])}</span>${esc(m.name)}<span class="trailing">${i===current?'⌄':'›'}</span></button>${i===current?`<div class="member-files"><button class="nav-row file-row" data-file="audio">${icon('audio')}访谈录音 ${String(recordingNo).padStart(2,'0')}<span class="trailing">08:32</span></button><button class="nav-row file-row current" data-file="document">${icon('doc')}访谈记录 · 草稿</button></div>`:''}`).join(''); }
function renderPaper(){const m=members[current],d=docs[current];$('#member-name').textContent=m.name;$('#document-name').textContent=m.title;$('#paper').innerHTML=`<div class="paper-kicker"><span>城市记忆 / ORAL HISTORY</span><span>记录编号　${String(current+1).padStart(2,'0')}</span></div><h2>访谈记录</h2><p class="paper-description">${esc(m.topic)}</p><table class="info-table"><tbody><tr><th>受访者</th><td>${esc(m.name)}</td><th>访谈人</th><td>许宁</td></tr><tr><th>访谈日期</th><td contenteditable="true">2026.11.02</td><th>访谈地点</th><td contenteditable="true">${esc(m.location)}</td></tr></tbody></table><h3 class="section-title"><span class="section-number">01</span>访谈内容</h3><section class="target-region ${target==='interview'?'is-target':''}" data-region="interview"><div class="target-caption"><span>● 当前录音目标</span>${icon('target')}</div><div class="editable" id="interview" contenteditable="true" role="textbox" aria-label="访谈内容" aria-multiline="true">${d.paragraphs.map(p=>`<p>${esc(p)}</p>`).join('')}</div><div class="source-link">${icon('audio')}来源：访谈录音 01 · 00:00—08:32</div></section><h3 class="section-title"><span class="section-number">02</span>补充备注</h3><section class="target-region ${target==='notes'?'is-target':''}" data-region="notes"><div class="target-caption"><span>● 当前录音目标</span>${icon('target')}</div><div class="editable" id="notes" contenteditable="true" role="textbox" aria-label="补充备注">${esc(d.note)}</div><div class="source-link">手动记录 · 无关联录音</div></section><div class="paper-foot"><span>城市记忆 · 口述访谈项目</span><span>工作草稿</span></div>`;wordCount();}
function wordCount(){$('#word-count').textContent=`${$('#paper').innerText.replace(/\s/g,'').length} 字`;}
function renderTranscript(){const list=$('#transcript-list');$('#pending-count').textContent=pending?'1':'0';if(tab==='pending'){list.innerHTML=pending?`<div class="pending-card"><div class="eyebrow">未分配 · 07:48</div><p>巷子里的老槐树还在，夏天大家会搬着椅子到树下乘凉。</p><button id="insert-pending">${icon('plus')}插入当前录音目标</button></div><div class="empty-state">这段文字尚未写入文档。选择录音目标后，可自行决定是否补入。</div>`:'<div class="empty-state">暂无未分配内容。后续未关联录音目标的文字会保留在这里。</div>';return;}
list.innerHTML=entries().map((e,i)=>`<div class="transcript-item ${i===selected?'selected':''} ${playing&&i===activeEntry()?'playing':''}" data-entry="${i}" role="button" tabindex="0" aria-label="定位到 ${fmt(e.time)}"><div class="utterance-head"><span class="speaker-mark">${e.letter}</span><span class="speaker-name">${i%2?esc(members[current].name):'访谈人'}</span><time>${fmt(e.time)}</time></div><p>${esc(e.text.replace(/^[问答]：/,''))}</p>${i===1?'<div class="revision">已人工修订</div>':''}</div>`).join('')+`<div class="transcript-item temporary"><div class="utterance-head"><span class="speaker-mark">B</span><span class="speaker-name">${esc(members[current].name)}</span><time>08:19</time></div><p>有些记忆是留在这些小地方的，比如门口的石阶，还有……</p><div class="revision"><span>···</span>临时转写 · 等待定稿</div></div>`;}
function activeEntry(){let idx=0;entries().forEach((e,i)=>{if(playPos>=e.time)idx=i});return idx}
function capture(){const p=$('#interview');docs[current].paragraphs=[...p.children].length?[...p.children].map(e=>e.textContent):[p.textContent];docs[current].note=$('#notes').textContent;}
function saved(){ $('#save-status').textContent='正在保存…';clearTimeout(dirtyTimer);dirtyTimer=setTimeout(()=>$('#save-status').textContent='草稿已保存 · 演示',2000);wordCount();}
function switchMember(i){if(i===current)return;if(recordState!=='idle'){openDialog('结束录音后切换',`<p>当前录音仍在进行。结束后会保留为一段独立录音。</p><button id="end-switch">结束录音并切换</button>`);$('#end-switch').onclick=()=>{endRecording();$('#dialog').close();switchMember(i)};return;}capture();current=i;target='interview';focusRegion='interview';playing=false;selected=-1;playPos=0;updatePlayer();renderMembers();renderPaper();renderTranscript();$('.sidebar').classList.remove('open');}
function openDialog(title,content,settings=false){lastFocus=document.activeElement;$('#dialog').classList.toggle('settings-dialog',settings);$('#dialog-title').textContent=title;$('#dialog-content').innerHTML=content;$('#dialog').showModal();}
$('#close-dialog').onclick=()=>$('#dialog').close();$('#dialog').addEventListener('close',()=>lastFocus?.focus());
$('#members').onclick=e=>{const m=e.target.closest('[data-member]');if(m)switchMember(+m.dataset.member);const f=e.target.closest('[data-file]');if(f){if(f.dataset.file==='audio'){setView('transcript');toast('已选择访谈录音，点击底部播放按钮试听演示。')}else{setView('document');$('#paper').scrollIntoView({block:'nearest'});}}};
$('#paper').addEventListener('focusin',e=>{const r=e.target.closest('[data-region]');if(r)focusRegion=r.dataset.region});
$('#paper').addEventListener('input',()=>{capture();saved()});
$('#set-target').onclick=()=>{target=focusRegion;document.querySelectorAll('[data-region]').forEach(el=>el.classList.toggle('is-target',el.dataset.region===target));$('#target-name').textContent=target==='interview'?'访谈内容':'补充备注';toast(`后续转写将写入「${$('#target-name').textContent}」`)};
document.querySelectorAll('[data-command]').forEach(b=>{b.onmousedown=e=>e.preventDefault();b.onclick=()=>{if(!$('#paper').contains(document.activeElement))$('#interview').focus();document.execCommand(b.dataset.command,false);capture();saved();}});
function setTab(t){tab=t;$('#transcript-tab').classList.toggle('active',t==='transcript');$('#unassigned-tab').classList.toggle('active',t==='pending');$('#transcript-tab').setAttribute('aria-selected',t==='transcript');$('#unassigned-tab').setAttribute('aria-selected',t==='pending');renderTranscript();}
$('#transcript-tab').onclick=()=>setTab('transcript');$('#unassigned-tab').onclick=()=>setTab('pending');
$('#transcript-list').onclick=e=>{const row=e.target.closest('[data-entry]');if(row){selected=+row.dataset.entry;playPos=entries()[selected].time;playing=false;updatePlayer();renderTranscript();}if(e.target.closest('#insert-pending')){const region=$(`#${target}`);const text='巷子里的老槐树还在，夏天大家会搬着椅子到树下乘凉。';if(target==='interview'){const p=document.createElement('p');p.textContent=text;region.appendChild(p)}else region.append(document.createTextNode(' '+text));pending=false;capture();saved();renderTranscript();toast('已插入当前录音目标');}};
$('#transcript-list').onkeydown=e=>{if((e.key==='Enter'||e.key===' ')&&e.target.matches('[data-entry]')){e.preventDefault();e.target.click()}};
$('#follow').onclick=()=>{setTab('transcript');$('#transcript-list').scrollTop=$('#transcript-list').scrollHeight;toast('已定位到最新转写')};
function updatePlayer(){$('#play-time').textContent=fmt(playPos);$('#seek').value=playPos;$('#play').innerHTML=icon(playing?'pause':'play');$('#play').setAttribute('aria-label',playing?'暂停示例播放':'播放示例录音');}
$('#play').onclick=()=>{playing=!playing;if(playPos>=512)playPos=0;updatePlayer();renderTranscript()};$('#seek').oninput=e=>{playPos=+e.target.value;updatePlayer();renderTranscript()};$('#speed').onclick=()=>{rate=rate===1?1.5:rate===1.5?2:1;$('#speed').textContent=rate+'×';};
function updateRecord(){$('#record-label').textContent=recordState==='idle'?'开始录音':recordState==='paused'?'继续录音':'录音中';$('#record').disabled=recordState==='recording';$('#pause').disabled=recordState!=='recording';$('#stop').disabled=recordState==='idle';$('#record-state').textContent=recordState==='idle'?'录音就绪':recordState==='paused'?'已暂停 · 演示':'正在录音 · 演示';$('#record-time').textContent=`${Math.floor(recordSeconds/3600).toString().padStart(2,'0')}:${fmt(recordSeconds%3600)}`;$('#transcript-state').textContent=recordState==='recording'?'演示转写运行中':recordState==='paused'?'转写已暂停':'已转写至 08:32';}
$('#record').onclick=()=>{if(recordState==='idle'){recordSeconds=0;recordingNo++;renderMembers();$('#audio-name').textContent=`访谈录音 ${String(recordingNo).padStart(2,'0')}.mp3`;toast('录音演示已开始，不会采集麦克风声音')}recordState='recording';updateRecord()};$('#pause').onclick=()=>{recordState='paused';updateRecord()};function endRecording(){recordState='idle';updateRecord();toast('录音演示已结束；再次开始将创建新的录音')}$('#stop').onclick=endRecording;
setInterval(()=>{if(recordState==='recording'){recordSeconds++;updateRecord()}if(playing){playPos=Math.min(512,playPos+rate);if(playPos>=512)playing=false;updatePlayer();renderTranscript()}},1000);
function showVersions(){openDialog('正式版本',snapshots.length?snapshots.map((s,i)=>`<div class="version-row"><div>正式版本 ${i+1}<small>${esc(s.title)} · ${s.time}</small></div><button data-snapshot="${i}">查看</button></div>`).join(''):'<p class="dialog-note">还没有正式版本。点击“确认最终记录”保存一份当前文档快照，后续编辑不会改变它。</p>');document.querySelectorAll('[data-snapshot]').forEach(b=>b.onclick=()=>{const s=snapshots[+b.dataset.snapshot];$('#dialog-title').textContent=`正式版本 ${+b.dataset.snapshot+1}`;$('#dialog-content').innerHTML=`<p class="dialog-note">${esc(s.title)} · ${s.time} · 只读快照</p><div class="snapshot">${esc(s.text)}</div>`;});}
$('#confirm').onclick=()=>{capture();const time=new Date().toLocaleTimeString('zh-CN',{hour12:false});snapshots.push({title:members[current].title,time,text:$('#paper').innerText});$('#version-count').textContent=snapshots.length;toast(`正式版本 ${snapshots.length} 已确认，工作草稿可继续编辑`)};$('#versions').onclick=showVersions;$('#history-link').onclick=showVersions;
$('#export').onclick=()=>openDialog('导出文档',`<p>默认导出已确认的正式版本，工作草稿仍可继续编辑。</p><div class="version-row"><span>DOCX 文档</span><span class="muted">${snapshots.length?'已有 '+snapshots.length+' 个正式版本':'尚未确认正式版本'}</span></div><p class="dialog-note">当前为页面展示原型，暂不生成 DOCX 文件。</p>`);
$('#import').onclick=()=>openDialog('导入录音或文档','<p>正式应用支持导入 WAV、M4A 等录音，以及 DOCX 模板与文档。</p><p class="dialog-note">当前为展示原型，示例数据已内置，暂不读取外部文件。</p>');
$('#templates').onclick=()=>{openDialog('模板库',`<p class="dialog-note">项目中的可复用文档结构</p><div class="version-row"><div>口述访谈记录<small>基本信息 / 访谈内容 / 补充备注</small></div><button id="view-template">查看示例</button></div><div class="version-row"><div>空白记录<small>自由编辑的正文文档</small></div><button id="blank-template">查看示例</button></div>`);$('#view-template').onclick=()=>{$('#dialog').close();setView('document');toast('当前文档使用「口述访谈记录」模板')};$('#blank-template').onclick=()=>{$('#dialog-title').textContent='空白记录 · 模板预览';$('#dialog-content').innerHTML='<div class="snapshot"><h3>记录标题</h3><p>日期：2026.11.02</p><p>在此填写记录正文……</p></div><p class="dialog-note">模板预览，当前工作草稿保持不变。</p>'}};
$('#settings').onclick=()=>{openDialog('工具设置',`<p class="dialog-note">转写与 AI 独立配置。演示中的设置仅保留在当前面板。</p><section class="setting-section"><h3>本机转写</h3><p>在本机处理录音，不上传音频。</p><label class="field">模型<select><option>中文流式模型 · 示例</option><option>录后转写模型 · 示例</option></select></label><label class="field">说话人分离<select><option>开启 · A / B 标注</option><option>关闭</option></select></label></section><section class="setting-section"><h3>在线转写</h3><p>启用后会向所选提供方上传录音。</p><label class="field">服务状态<select><option>未启用</option><option>配置预览（不连接）</option></select></label><label class="field">服务商<select><option>Qwen-ASR-Realtime · 候选</option></select></label><label class="field">API 密钥<input type="password" autocomplete="off" placeholder="仅展示，不要填写真实密钥"></label><button id="test-connection" style="margin-top:14px">连接测试</button></section><section class="setting-section"><h3>AI 文档整理</h3><p>仅处理指定正式版本，输出独立派生文档。</p><label class="field">服务地址<input placeholder="填写兼容接口地址"></label><label class="field">模型<input placeholder="填写文本模型名称"></label></section><button id="save-settings">完成</button>`,true);$('#test-connection').onclick=()=>toast('展示原型不发起网络连接');$('#save-settings').onclick=()=>{$('#dialog').close();toast('配置预览已关闭')}};
$('#device').onclick=()=>{openDialog('录音输入',`<label class="field">输入来源<select><option>内置麦克风</option><option>电脑播放声音</option><option>麦克风与电脑声音混合</option></select></label><p class="dialog-note">当前仅预览输入选项，不请求设备权限。</p>`)};
$('#add-member').onclick=()=>{openDialog('新建项目成员','<label class="field">成员名称<input id="new-name" maxlength="20" placeholder="输入成员名称"></label><button id="create-member" style="margin-top:16px">创建成员</button>');$('#create-member').onclick=()=>{const name=$('#new-name').value.trim();if(!name){$('#new-name').focus();return}members.push({name,role:'受访者',title:`${name} · 访谈记录`,topic:'访谈主题待补充',location:'待填写'});docs.push({paragraphs:['请填写访谈内容，或将这里设为录音目标。'],note:'请填写补充备注。'});$('#dialog').close();renderMembers();switchMember(members.length-1)}};
function setView(view){document.body.classList.toggle('transcript-view',view==='transcript');document.querySelectorAll('[data-view]').forEach(b=>b.classList.toggle('active',b.dataset.view===view));}document.querySelectorAll('[data-view]').forEach(b=>b.onclick=()=>setView(b.dataset.view));$('#menu').onclick=()=>$('.sidebar').classList.toggle('open');
function search(){const q=$('#search').value.trim();if(!q){toast('请输入要查找的文字');return}capture();const results=[];docs.forEach((d,i)=>[...d.paragraphs,d.note].forEach(t=>{if(t.includes(q))results.push({i,t})}));openDialog('搜索结果',`<p class="dialog-note">“${esc(q)}” · 找到 ${results.length} 处内容</p>`+results.map((r,j)=>`<button class="search-result" data-result="${j}"><small>${esc(members[r.i].name)} / ${esc(members[r.i].title)}</small>${esc(r.t)}</button>`).join('')+(results.length?'':'<p>没有找到匹配内容，试试“老街”或“书店”。</p>'));document.querySelectorAll('[data-result]').forEach(b=>b.onclick=()=>{$('#dialog').close();switchMember(results[+b.dataset.result].i);setView('document');toast('已打开匹配文档')});}$('#search').onkeydown=e=>{if(e.key==='Enter')search()};document.addEventListener('keydown',e=>{if((e.ctrlKey||e.metaKey)&&e.key.toLowerCase()==='k'){e.preventDefault();if(getComputedStyle($('.search')).display==='none'){toast('项目搜索可在桌面宽度使用')}else $('#search').focus();}});
renderMembers();renderPaper();renderTranscript();updatePlayer();updateRecord();
